// Level data types. The data itself is generated by tools/gen_levels.py,
// which checks every map before writing main/levels.c.
#pragma once

#include <stdbool.h>
#include <stdint.h>

#include "config.h"

typedef enum { LOOT_GOLD, LOOT_WATCH, LOOT_JADE, LOOT_VASE, LOOT_PAINTING, LOOT_JEWEL, LOOT_BAR, LOOT_KINDS } loot_kind_t;

typedef struct {
    const char *name;                 // 5x7 font characters only
    const char *sub;
    bool tutorial, bonus;
    uint16_t time;                    // seconds on the clock
    uint8_t floors, w;                // w columns of TILE px
    uint8_t pal[4][3];                // wall, stripe, dado, floor
    const char *rows[MAX_FLOORS];     // floors top to bottom, one char per column
    uint8_t nloot;                    // the $ tiles in reading order get these
    uint8_t loot_kind[MAX_LOOT];
    uint16_t loot_value[MAX_LOOT];
    uint8_t nlights;                  // bonus spotlights: floor, beam width, speed px/s
    uint8_t lights[MAX_LIGHTS][3];
} level_t;

extern const level_t g_levels[];
extern const int g_level_count;
